## ---- 01: A Worked Empirical Example  (qmd line 178) ----------------------------------

library(dnsr)

maturities <- c(0.25, 0.5, 1, 2, 3, 5, 7, 10, 20, 30)
yields     <- c(4.80, 4.70, 4.50, 4.30, 4.25, 4.20, 4.22, 4.25, 4.35, 4.40)/100

# Build loading matrix: L1 (level), L2 (slope), L3 (curvature)
# lambda = 0.0609 is per month, so evaluate the loadings in months.
# The equivalent year-units pair is lambda = 0.7308 with m = maturities.
lambda <- 0.0609
m  <- maturities * 12
L2 <- (1 - exp(-lambda * m)) / (lambda * m)
L  <- cbind(L1 = 1, L2 = L2, L3 = L2 - exp(-lambda * m))

fit <- lm(yields ~ 0 + L)  # no intercept; L1 serves
beta <- coef(fit)
# beta: (level, slope, curvature)


## ---- 02: Cross-Sectional Fit with `dnsr::fit_ns_model`  (qmd line 271) ---------------

library(dnsr)

mats   <- c(0.25, 0.5, 1, 2, 3, 5, 7, 10, 20, 30)
yields <- c(4.80, 4.70, 4.50, 4.30, 4.25, 4.20, 4.22,
            4.25, 4.35, 4.40) / 100

# mats is in years, so lambda is per year: Diebold-Li's 0.0609 per
# month is 0.0609 * 12. Equivalently, ns_lambda(2.4539) -- the decay
# rate that puts the curvature hump at 29.4 months.
fit <- fit_ns_model(maturities = mats, yields = yields,
                    initial_lambda = 0.7308,
                    lambda_constraint = "fixed")
fit$parameters    # beta1, beta2, beta3, lambda
fit$rmse

# Reconstruct fitted curve via dnsr::calculate_dns_yields
betas <- as.numeric(fit$parameters[c("beta1","beta2","beta3")])
fitted_yields <- calculate_dns_yields(
  factors = matrix(betas, nrow = 1,
                   dimnames = list(NULL, c("beta1","beta2","beta3"))),
  maturities = mats, lambda = 0.7308
)
residuals <- yields - as.numeric(fitted_yields)
sqrt(mean(residuals^2))


## ---- 03: Loading Matrix and OLS Sanity Check  (qmd line 300) -------------------------

# Helper: build the NS loading matrix (didactic; equivalent loadings
# are used internally by dnsr::fit_ns_model and calculate_dns_yields)
ns_loadings <- function(m, lambda) {
  L1 <- rep(1, length(m))
  L2 <- (1 - exp(-lambda * m)) / (lambda * m)
  L3 <- L2 - exp(-lambda * m)
  cbind(L1, L2, L3)
}

L <- ns_loadings(mats, 0.7308)   # mats in years, so lambda per year
beta <- coef(lm(yields ~ 0 + L))
# Should match fit$parameters[c("beta1","beta2","beta3")] above


## ---- 04: Estimating $\lambda$ Nonlinearly  (qmd line 317) ----------------------------

# Use dnsr's joint estimation by relaxing the lambda constraint.
# The lambda bounds are the fourth element of each vector, in the same
# per-year units as mats: 0.01 to 2 puts the hump anywhere from 179
# years out to 11 months. Bounds that exclude the optimum leave lambda
# resting on one of them, which fit_ns_model warns about.
fit_free <- fit_ns_model(maturities = mats, yields = yields,
                         initial_lambda = 0.7308,
                         lambda_constraint = "constrained",
                         lower_bounds = c(-0.1, -0.5, -0.5, 0.01),
                         upper_bounds = c( 0.2,  0.5,  0.5, 2.00))
fit_free$parameters   # lambda 0.569/yr: hump at 3.15 years, RMSE 1.4bp


## ---- 05: Svensson Extension  (qmd line 333) ------------------------------------------

# Helper for the Svensson dual-decay form (extension to fit_ns_model)
sv_loadings <- function(m, lam1, lam2) {
  cbind(ns_loadings(m, lam1),
        (1 - exp(-lam2*m))/(lam2*m) - exp(-lam2*m))
}
# Both decay rates are per year here, converted from the per-month
# 0.0609 and 0.018: second hump at 8.3 years.
fit_sv <- lm(yields ~ 0 + sv_loadings(mats, 0.7308, 0.216))


## ---- 06: Diagnostic Plot  (qmd line 346) ---------------------------------------------

library(ggplot2)

fit_df <- rbind(
  data.frame(maturity = mats, yield = yields * 100,
             series = "Observed"),
  data.frame(maturity = mats, yield = as.numeric(fitted_yields) * 100,
             series = "NS fit")
)
ggplot(fit_df, aes(maturity, yield, colour = series)) +
  geom_point(data = subset(fit_df, series == "Observed")) +
  geom_line(data = subset(fit_df, series == "NS fit")) +
  geom_hline(aes(yintercept = betas[1] * 100, colour = "Long-run"),
             linetype = 2) +
  labs(x = "Maturity (yrs)", y = "Yield (%)", colour = NULL) +
  theme_minimal()


